import React from 'react';
import './App.css'; // 화면 스타일을 꾸미고 싶을 때 사용

function App() {
  return (
    <div className="App">
      <h1>부산 공모전 프로젝트 시작!</h1>
      <p>여기서부터 원하는 화면을 만드시면 됩니다.</p>
    </div>
  );
}

export default App;
